    [7, 0, 8, 8, 0, 6, 0, 3, 3, 0],
    [7, 0, 8, 8, 0, 6, 0, 3, 3, 0],
]

# Extract unique colors (non-zero)
test_colors = set()
for row in test_input:
    for cell in row:
        if cell != 0:
            test_colors.add(cell)
print("Test input colors:", test_colors)

# Build output
result = [[0]*10 for _ in range(10)]

# Place each color
for c in test_colors:
    tl_row, tl_col = top_left_pos(c)

    if c in patterns:
        # Known pattern
        for r_off, c_off in patterns[c]:
            r = tl_row + r_off
            col = tl_col + c_off
            if 0 <= r < 10 and 0 <= col < 10:
                result[r][col] = c
    else:
        # Unknown color: use vertical line pattern
        # For unknown colors, let's use a simpler pattern: 2x2 square
        for r_off in [0, 1]:
            for c_off in [0, 1]:
                r = tl_row + r_off
                col = tl_col + c_off
